def parse_duration(text: str) -> int:
    if not text or not isinstance(text, str):
        raise ValueError("Empty or invalid string")

    text = text.strip()
    if not text:
        raise ValueError("Empty string")

    # Validate only h, m, s, digits, and optional units
    import re
    if not re.match(r'^\d*[hms]$', text):
        raise ValueError("Invalid string: contains invalid characters or units")

    # Split by units in order h, m, s
    parts = []
    if 'h' in text:
        h_idx = text.find('h')
        if h_idx == 0 or h_idx == len(text) - 1:
            raise ValueError("Invalid format")
        h_val = int(text[:h_idx])
        parts.append(('h', h_val))
    if 'm' in text:
        m_idx = text.find('m')
        if m_idx == 0 or m_idx == len(text) - 1:
            raise ValueError("Invalid format")
        m_val = int(text[:m_idx])
        parts.append(('m', m_val))
    if 's' in text:
        s_idx = text.find('s')
        if s_idx == 0 or s_idx == len(text) - 1:
            raise ValueError("Invalid format")
        s_val = int(text[:s_idx])
        parts.append(('s', s_val))

    # If no valid units, raise error
    if not parts:
        raise ValueError("No valid units found")

    total = 0
    for unit, val in parts:
        if unit == 'h':
            total += val * 3600
        elif unit == 'm':
            total += val * 60
        elif unit == 's':
            total += val

    return total

