def parse_duration(text: str) -> int:
    if not text or not text.strip():
        raise ValueError("Empty or invalid string")

    text = text.strip()
    total_seconds = 0

    for unit in ['h', 'm', 's']:
        if unit in text:
            prefix, suffix = text.rsplit(unit, 1)
            try:
                total_seconds += int(prefix) * (60 if unit == 'h' else 60 if unit == 'm' else 1)
            except ValueError:
                raise ValueError(f"Invalid number prefix for unit '{unit}'")
            text = prefix

    if text != '':
        raise ValueError(f"Invalid characters found: {text}")

    return total_seconds

