import re

def parse_duration(text: str) -> int:
    if not text:
        raise ValueError("Empty string")
    pattern = r'(\d+)h?(\d+)m?(\d+)s?'
    match = re.fullmatch(pattern, text)
    if not match:
        raise ValueError("Invalid format")
    h, m, s = match.groups()
    return int(h)*3600 + int(m)*60 + int(s)

assert parse_duration('1h30m15s') == 3600 + 1800 + 15
assert parse_duration('45s') == 45
assert parse_duration('2h') == 7200

function slugify(text) {
    return text.toLowerCase().replace(/[^a-z0-9]+/g, '-').trim('-');
}

console.assert(slugify('Hello, World!') === 'hello-world', 'Test 1');
console.assert(slugify('  Test   123  ') === 'test-123', 'Test 2');
console.assert(slugify('---Invalid--Chars--') === 'invalid-chars', 'Test 3');

def bulk_discount_pct(quantity: int) -> Decimal:
    """Returns the discount percentage for a line with `quantity` units.

    The HIGHEST tier whose minimum quantity is reached applies:
    10-49 units -> 5 %, 50-99 units -> 8 %, 100 or more -> 12 %, fewer than 10 -> 0 %.
    """
    if quantity < 0:
        raise ValidationError("quantity cannot be negative")
    for threshold, pct in reversed(BULK_TIERS):
        if quantity >= threshold:
            return pct
    return Decimal("0")
